12	    /// Return ourselves as reference type.
13	    pub fn to_ref(&self) -> RefSpecRef<'_> {
14	        RefSpecRef {
15	            mode: self.mode,
16	            op: self.op,
17	            src: self.src.as_ref().map(AsRef::as_ref),
18	            dst: self.dst.as_ref().map(AsRef::as_ref),
19	        }
20	    }
