110	    /// Always returns the remote side, whose actual side in the refspec depends on how it was parsed.
111	    pub fn remote(&self) -> Option<&BStr> {
112	        match self.op {
113	            Operation::Push => self.dst,
114	            Operation::Fetch => self.src,
115	        }
116	    }
