118	    /// Always returns the local side, whose actual side in the refspec depends on how it was parsed.
119	    pub fn local(&self) -> Option<&BStr> {
120	        match self.op {
121	            Operation::Push => self.src,
122	            Operation::Fetch => self.dst,
123	        }
124	    }
