128	    ///
129	    /// This means it starts with `refs/`. Note that it won't contain more than two components, like `refs/heads/`
130	    pub fn prefix(&self) -> Option<&BStr> {
131	        if self.mode == Mode::Negative {
132	            return None;
133	        }
134	        let source = match self.op {
135	            Operation::Fetch => self.source(),
136	            Operation::Push => self.destination(),
