+
+        let expected_object_hash = repo.object_hash();
+        if ref_map.object_hash != expected_object_hash {
+            return Err(Error::IncompatibleObjectHash {
+                local: expected_object_hash,
+                remote: ref_map.object_hash,
+            });
+        }
+
+        let fetch_options = gix_protocol::fetch::Options {
+            shallow_file: repo.shallow_file(),
+            shallow: &self.shallow,
+            tags: con.remote.fetch_tags,
+            reject_shallow_remote: repo
+                .config
+                .resolved
+                .boolean_filter("clone.rejectShallow", &mut repo.filter_config_section())
+                .map(|val| Clone::REJECT_SHALLOW.enrich_error(val))
+                .transpose()?
+                .unwrap_or(false),
+        };
+        let context = gix_protocol::fetch::Context {
+            handshake: &mut handshake,
+            transport: &mut con.transport.inner,
+            user_agent: repo.config.user_agent_tuple(),
+            trace_packetlines: con.trace,
+        };
+
+        let negotiator = repo
+            .config
+            .resolved
+            .string(Fetch::NEGOTIATION_ALGORITHM)
+            .map(|n| Fetch::NEGOTIATION_ALGORITHM.try_into_negotiation_algorithm(n))
+            .transpose()
+            .with_leniency(repo.config.lenient_config)?
+            .unwrap_or(Algorithm::Consecutive)
+            .into_negotiator();
+        let graph_repo = {
+            let mut r = repo.clone();
+            // assure that checking for unknown server refs doesn't trigger ODB refreshes.
+            r.objects.refresh = RefreshMode::Never;
+            // we cache everything of importance in the graph and thus don't need an object cache.
+            r.objects.unset_object_cache();
+            r
+        };
+        let cache = graph_repo.commit_graph_if_enabled().ok().flatten();
+        let mut graph = graph_repo.revision_graph(cache.as_ref());
+        let alternates = repo.objects.store_ref().alternate_db_paths()?;
+        let mut negotiate = Negotiate {
+            objects: &graph_repo.objects,
+            refs: &graph_repo.refs,
+            graph: &mut graph,
+            alternates,
+            ref_map,
+            shallow: &self.shallow,
+            tags: con.remote.fetch_tags,
+            negotiator,
+            open_options: repo.options.clone(),
+        };
+
+        let write_pack_options = gix_pack::bundle::write::Options {
+            thread_limit: config::index_threads(repo)?,
+            index_version: config::pack_index_version(repo)?,
+            iteration_mode: gix_pack::data::input::Mode::Verify,
+            object_hash: repo.object_hash(),
+            alloc_limit_bytes: repo.config.alloc_limit_bytes,
+        };
+        let mut write_pack_bundle = None;
+
+        let res = gix_protocol::fetch(
+            &mut negotiate,
+            |reader, progress, should_interrupt| -> Result<bool, gix_pack::bundle::write::Error> {
+                let mut may_read_to_end = false;
+                write_pack_bundle = if matches!(self.dry_run, fetch::DryRun::No) {
+                    let res = gix_pack::Bundle::write_to_directory(
+                        reader,
+                        Some(&repo.objects.store_ref().path().join("pack")),
+                        progress,
+                        should_interrupt,
+                        Some(Box::new({
+                            let repo = repo.clone();
+                            repo.objects
+                        })),
+                        write_pack_options,
+                    )?;
+                    may_read_to_end = true;
+                    Some(res)
+                } else {
+                    None
+                };
+                Ok(may_read_to_end)
+            },
+            progress,
+            should_interrupt,
+            context,
+            fetch_options,
+        )
+        .await?;
+        let negotiate = res.map(|v| outcome::Negotiate {
+            graph: graph.detach(),
+            rounds: v.negotiate.rounds,
+        });
+
+        if matches!(handshake.server_protocol_version, gix_protocol::transport::Protocol::V2) {
+            gix_protocol::indicate_end_of_interaction(&mut con.transport.inner, con.trace)
+                .await
+                .ok();
+        }
+
+        let update_refs = refs::update(
+            repo,
+            self.reflog_message
+                .take()
+                .unwrap_or_else(|| RefLogMessage::Prefixed { action: "fetch".into() }),
+            &self.ref_map.mappings,
+            con.remote.fetch_refspecs(),
+            &self.ref_map.extra_refspecs,
+            con.remote.fetch_tags,
+            self.dry_run,
+            self.write_packed_refs,
+        )?;
+
+        if let Some(bundle) = write_pack_bundle.as_mut() {
+            if !update_refs.edits.is_empty() || bundle.index.num_objects == 0 {
+                if let Some(path) = bundle.keep_path.take() {
+                    std::fs::remove_file(&path).map_err(|err| Error::RemovePackKeepFile { path, source: err })?;
+                }
+            }
+        }
+
+        let out = Outcome {
+            handshake,
+            ref_map: std::mem::take(&mut self.ref_map),
+            status: match write_pack_bundle {
+                Some(write_pack_bundle) => Status::Change {
+                    write_pack_bundle,
+                    update_refs,
+                    negotiate: negotiate.expect("if we have a pack, we always negotiated it"),
+                },
+                None => Status::NoPackReceived {
+                    dry_run: matches!(self.dry_run, fetch::DryRun::Yes),
+                    negotiate,
+                    update_refs,
+                },
+            },
+        };
+        Ok(out)
+    }
+}
+
+struct Negotiate<'a, 'b, 'c> {
+    objects: &'a crate::OdbHandle,
+    refs: &'a gix_ref::file::Store,
+    graph: &'a mut gix_negotiate::Graph<'b, 'c>,
+    alternates: Vec<PathBuf>,
+    ref_map: &'a gix_protocol::fetch::RefMap,
+    shallow: &'a gix_protocol::fetch::Shallow,
+    tags: gix_protocol::fetch::Tags,
+    negotiator: Box<dyn gix_negotiate::Negotiator>,
+    open_options: crate::open::Options,
+}
+
+impl gix_protocol::fetch::Negotiate for Negotiate<'_, '_, '_> {
+    fn mark_complete_and_common_ref(&mut self) -> Result<negotiate::Action, negotiate::Error> {
+        negotiate::mark_complete_and_common_ref(
+            &self.objects,
+            self.refs,
+            {
+                let alternates = std::mem::take(&mut self.alternates);
+                let open_options = self.open_options.clone();
+                move || -> Result<_, std::convert::Infallible> {
+                    Ok(alternates
+                        .into_iter()
+                        .filter_map(move |path| {
+                            path.ancestors()
+                                .nth(1)
+                                .and_then(|git_dir| crate::open_opts(git_dir, open_options.clone()).ok())
+                        })
+                        .map(|repo| (repo.refs, repo.objects)))
+                }
+            },
+            self.negotiator.deref_mut(),
+            &mut *self.graph,
+            self.ref_map,
+            self.shallow,
+            negotiate::make_refmapping_ignore_predicate(self.tags, self.ref_map),
+        )
+    }
+
+    fn add_wants(&mut self, arguments: &mut Arguments, remote_ref_target_known: &[bool]) -> bool {
+        negotiate::add_wants(
+            self.objects,
+            arguments,
+            self.ref_map,
+            remote_ref_target_known,
+            self.shallow,
+            negotiate::make_refmapping_ignore_predicate(self.tags, self.ref_map),
+        )
+    }
+
+    fn one_round(
+        &mut self,
+        state: &mut negotiate::one_round::State,
+        arguments: &mut Arguments,
+        previous_response: Option<&gix_protocol::fetch::Response>,
+    ) -> Result<(negotiate::Round, bool), negotiate::Error> {
+        negotiate::one_round(
+            self.negotiator.deref_mut(),
+            &mut *self.graph,
+            state,
+            arguments,
+            previous_response,
+        )
+    }
+}
diff --git a/tmp/up_spec.rs b/tmp/up_spec.rs
new file mode 100644
index 000000000..487251f30
--- /dev/null
+++ b/tmp/up_spec.rs
@@ -0,0 +1,272 @@
+use bstr::{BStr, BString, ByteSlice};
+
+use crate::{
+    Instruction, RefSpec, RefSpecRef,
+    instruction::{Fetch, Push},
+    parse::Operation,
+    types::Mode,
+};
+
+/// Conversion. Use the [`RefSpecRef`][RefSpec::to_ref()] type for more usage options.
+impl RefSpec {
+    /// Return ourselves as reference type.
+    pub fn to_ref(&self) -> RefSpecRef<'_> {
+        RefSpecRef {
+            mode: self.mode,
+            op: self.op,
+            src: self.src.as_ref().map(AsRef::as_ref),
+            dst: self.dst.as_ref().map(AsRef::as_ref),
+        }
+    }
+
+    /// Return true if the spec stats with a `+` and thus forces setting the reference.
+    pub fn allow_non_fast_forward(&self) -> bool {
+        matches!(self.mode, Mode::Force)
+    }
+}
+
+mod impls {
+    use std::{
+        cmp::Ordering,
+        hash::{Hash, Hasher},
+    };
+
+    use crate::{RefSpec, RefSpecRef};
+
+    impl From<RefSpecRef<'_>> for RefSpec {
+        fn from(v: RefSpecRef<'_>) -> Self {
+            v.to_owned()
+        }
+    }
+
+    impl Hash for RefSpec {
+        fn hash<H: Hasher>(&self, state: &mut H) {
+            self.to_ref().hash(state);
+        }
+    }
+
+    impl Hash for RefSpecRef<'_> {
+        fn hash<H: Hasher>(&self, state: &mut H) {
+            self.instruction().hash(state);
+        }
+    }
+
+    impl PartialEq for RefSpec {
+        fn eq(&self, other: &Self) -> bool {
+            self.to_ref().eq(&other.to_ref())
+        }
+    }
+
+    impl PartialEq for RefSpecRef<'_> {
+        fn eq(&self, other: &Self) -> bool {
+            self.instruction().eq(&other.instruction())
+        }
+    }
+
+    impl PartialOrd for RefSpecRef<'_> {
+        fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
+            Some(self.cmp(other))
+        }
+    }
+
+    #[allow(clippy::non_canonical_partial_ord_impl)]
+    impl PartialOrd for RefSpec {
+        fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
+            Some(self.to_ref().cmp(&other.to_ref()))
+        }
+    }
+
+    impl Ord for RefSpecRef<'_> {
+        fn cmp(&self, other: &Self) -> Ordering {
+            self.instruction().cmp(&other.instruction())
+        }
+    }
+
+    impl Ord for RefSpec {
+        fn cmp(&self, other: &Self) -> Ordering {
+            self.to_ref().cmp(&other.to_ref())
+        }
+    }
+}
+
+/// Access
+impl<'a> RefSpecRef<'a> {
+    /// Return the left-hand side of the spec, typically the source.
+    /// It takes many different forms so don't rely on this being a ref name.
+    ///
+    /// It's not present in case of deletions.
+    pub fn source(&self) -> Option<&BStr> {
+        self.src
+    }
+
+    /// Return the right-hand side of the spec, typically the destination.
+    /// It takes many different forms so don't rely on this being a ref name.
+    ///
+    /// It's not present in case of source-only specs.
+    pub fn destination(&self) -> Option<&BStr> {
+        self.dst
+    }
+
+    /// Always returns the remote side, whose actual side in the refspec depends on how it was parsed.
+    pub fn remote(&self) -> Option<&BStr> {
+        match self.op {
+            Operation::Push => self.dst,
+            Operation::Fetch => self.src,
+        }
+    }
+
+    /// Always returns the local side, whose actual side in the refspec depends on how it was parsed.
+    pub fn local(&self) -> Option<&BStr> {
+        match self.op {
+            Operation::Push => self.src,
+            Operation::Fetch => self.dst,
+        }
+    }
+
+    /// Derive the prefix from the [`source`][Self::source()] side of this spec if this is a fetch spec,
+    /// or the [`destination`][Self::destination()] side if it is a push spec, if it is possible to do so without ambiguity.
+    ///
+    /// Exact refs starting with `refs/` are returned unchanged, like `refs/heads/main`
+    /// or `refs/namespaces/foo/refs/heads/main`. Simple Git-style glob refspecs return
+    /// the portion up to their single `*`, like `refs/heads/` or `refs/namespaces/foo/refs/heads/`.
+    ///
+    /// More complex wildcard patterns don't have a Git-compatible ref-prefix and thus return `None`.
+    pub fn prefix(&self) -> Option<&BStr> {
+        if self.mode == Mode::Negative {
+            return None;
+        }
+        let source = match self.op {
+            Operation::Fetch => self.source(),
+            Operation::Push => self.destination(),
+        }?;
+        if source == "HEAD" {
+            return source.into();
+        }
+
+        let sans_refs_prefix = source.strip_prefix(b"refs/")?;
+        if let Some(star_pos) = sans_refs_prefix.find_byte(b'*') {
+            if star_pos == 0
+                || sans_refs_prefix[star_pos + 1..].contains(&b'*')
+                || sans_refs_prefix.find_byteset(b"?[]\\").is_some()
+            {
+                return None;
+            }
+            let prefix = &source[.."refs/".len() + star_pos];
+            return (!prefix.is_empty()).then_some(prefix.as_bstr());
+        }
+        Some(source)
+    }
+
+    /// As opposed to [`prefix()`][Self::prefix], if the latter is `None` it will expand to all possible prefixes and place them in `out`.
+    ///
+    /// Note that only the `source` side is considered.
+    pub fn expand_prefixes(&self, out: &mut Vec<BString>) {
+        match self.prefix() {
+            Some(prefix) => out.push(prefix.into()),
+            None => {
+                let source = match match self.op {
+                    Operation::Fetch => self.source(),
+                    Operation::Push => self.destination(),
+                } {
+                    Some(source) => source,
+                    None => return,
+                };
+                if let Some(rest) = source.strip_prefix(b"refs/") {
+                    if !rest.contains(&b'/') {
+                        out.push(source.into());
+                    }
+                    return;
+                } else if gix_hash::ObjectId::from_hex(source).is_ok() {
+                    return;
+                }
+                expand_partial_name(source, |expanded| {
+                    out.push(expanded.into());
+                    None::<()>
+                });
+            }
+        }
+    }
+
+    /// Transform the state of the refspec into an instruction making clear what to do with it.
+    pub fn instruction(&self) -> Instruction<'a> {
+        match self.op {
+            Operation::Fetch => match (self.mode, self.src, self.dst) {
+                (Mode::Normal | Mode::Force, Some(src), None) => Instruction::Fetch(Fetch::Only { src }),
+                (Mode::Normal | Mode::Force, Some(src), Some(dst)) => Instruction::Fetch(Fetch::AndUpdate {
+                    src,
+                    dst,
+                    allow_non_fast_forward: matches!(self.mode, Mode::Force),
+                }),
+                (Mode::Negative, Some(src), None) => Instruction::Fetch(Fetch::Exclude { src }),
+                (mode, src, dest) => {
+                    unreachable!(
+                        "BUG: fetch instructions with {:?} {:?} {:?} are not possible",
+                        mode, src, dest
+                    )
+                }
+            },
+            Operation::Push => match (self.mode, self.src, self.dst) {
+                (Mode::Normal | Mode::Force, Some(src), None) => Instruction::Push(Push::Matching {
+                    src,
+                    dst: src,
+                    allow_non_fast_forward: matches!(self.mode, Mode::Force),
+                }),
+                (Mode::Normal | Mode::Force, None, Some(dst)) => {
+                    Instruction::Push(Push::Delete { ref_or_pattern: dst })
+                }
+                (Mode::Normal | Mode::Force, None, None) => Instruction::Push(Push::AllMatchingBranches {
+                    allow_non_fast_forward: matches!(self.mode, Mode::Force),
+                }),
+                (Mode::Normal | Mode::Force, Some(src), Some(dst)) => Instruction::Push(Push::Matching {
+                    src,
+                    dst,
+                    allow_non_fast_forward: matches!(self.mode, Mode::Force),
+                }),
+                (Mode::Negative, Some(src), None) => Instruction::Push(Push::Exclude { src }),
+                (mode, src, dest) => {
+                    unreachable!(
+                        "BUG: push instructions with {:?} {:?} {:?} are not possible",
+                        mode, src, dest
+                    )
+                }
+            },
+        }
+    }
+}
+
+/// Conversion
+impl RefSpecRef<'_> {
+    /// Convert this ref into a standalone, owned copy.
+    pub fn to_owned(&self) -> RefSpec {
+        RefSpec {
+            mode: self.mode,
+            op: self.op,
+            src: self.src.map(ToOwned::to_owned),
+            dst: self.dst.map(ToOwned::to_owned),
+        }
+    }
+}
+
+pub(crate) fn expand_partial_name<T>(name: &BStr, mut cb: impl FnMut(&BStr) -> Option<T>) -> Option<T> {
+    use bstr::ByteVec;
+    let mut buf = BString::from(Vec::with_capacity(128));
+    for (base, append_head) in [
+        ("", false),
+        ("refs/", false),
+        ("refs/tags/", false),
+        ("refs/heads/", false),
+        ("refs/remotes/", false),
+        ("refs/remotes/", true),
+    ] {
+        buf.clear();
+        buf.push_str(base);
+        buf.push_str(name);
+        if append_head {
+            buf.push_str("/HEAD");
+        }
+        if let Some(res) = cb(buf.as_ref()) {
+            return Some(res);
+        }
+    }
+    None
+}
diff --git a/tmp/up_types.rs b/tmp/up_types.rs
new file mode 100644
index 000000000..adf822fbd
--- /dev/null
+++ b/tmp/up_types.rs
@@ -0,0 +1,276 @@
+use std::path::PathBuf;
+
+use crate::fetch::response::{Acknowledgement, ShallowUpdate, WantedRef};
+
+/// Options for use in [`fetch()`](`crate::fetch()`)
+#[derive(Debug, Clone)]
+pub struct Options<'a> {
+    /// The path to the file containing the shallow commit boundary.
+    ///
+    /// When needed, it will be locked in preparation for being modified.
+    pub shallow_file: PathBuf,
+    /// How to deal with shallow repositories. It does affect how negotiations are performed.
+    pub shallow: &'a Shallow,
+    /// Describe how to handle tags when fetching.
+    pub tags: Tags,
+    /// If `true`, if we fetch from a remote that only offers shallow clones, the operation will fail with an error
+    /// instead of writing the shallow boundary to the shallow file.
+    pub reject_shallow_remote: bool,
+}
+
+/// For use in [`crate::Handshake::prepare_lsrefs_or_extract_refmap()`] and [`fetch`](crate::fetch()).
+#[cfg(feature = "handshake")]
+pub struct Context<'a, T> {
+    /// The outcome of the handshake performed with the remote.
+    ///
+    /// Note that it's mutable as depending on the protocol, it may contain refs that have been sent unconditionally.
+    pub handshake: &'a mut crate::Handshake,
+    /// The transport to use when making an `ls-refs` or `fetch` call.
+    ///
+    /// This is always done if the underlying protocol is V2, which is implied by the absence of refs in the `handshake` outcome.
+    pub transport: &'a mut T,
+    /// How to self-identify during the `ls-refs` call in [`crate::Handshake::prepare_lsrefs_or_extract_refmap()`] or the `fetch` call in [`fetch()`](crate::fetch()).
+    ///
+    /// This could be read from the `gitoxide.userAgent` configuration variable.
+    pub user_agent: (&'static str, Option<std::borrow::Cow<'static, str>>),
+    /// If `true`, output all packetlines using the `gix-trace` machinery.
+    pub trace_packetlines: bool,
+}
+
+#[cfg(feature = "fetch")]
+mod with_fetch {
+    use bstr::ByteSlice;
+
+    use crate::fetch::{self, negotiate, refmap};
+
+    /// For use in [`fetch`](crate::fetch()).
+    pub struct NegotiateContext<'a, 'b, 'c, Objects, Alternates, AlternatesOut, AlternatesErr, Find>
+    where
+        Objects: gix_object::Find + gix_object::FindHeader + gix_object::Exists,
+        Alternates: FnOnce() -> Result<AlternatesOut, AlternatesErr>,
+        AlternatesErr: Into<Box<dyn std::error::Error + Send + Sync + 'static>>,
+        AlternatesOut: Iterator<Item = (gix_ref::file::Store, Find)>,
+        Find: gix_object::Find,
+    {
+        /// Access to the object database.
+        /// *Note* that the `exists()` calls must not trigger a refresh of the ODB packs as plenty of them might fail, i.e. find on object.
+        pub objects: &'a Objects,
+        /// Access to the git references database.
+        pub refs: &'a gix_ref::file::Store,
+        /// A function that returns an iterator over `(refs, objects)` for each alternate repository, to assure all known objects are added also according to their tips.
+        pub alternates: Alternates,
+        /// The implementation that performs the negotiation later, i.e. prepare wants and haves.
+        pub negotiator: &'a mut dyn gix_negotiate::Negotiator,
+        /// The commit-graph for use by the `negotiator` - we populate it with tips to initialize the graph traversal.
+        pub graph: &'a mut gix_negotiate::Graph<'b, 'c>,
+    }
+
+    /// A trait to encapsulate steps to negotiate the contents of the pack.
+    ///
+    /// Typical implementations use the utilities found in the [`negotiate`] module.
+    pub trait Negotiate {
+        /// Typically invokes [`negotiate::mark_complete_and_common_ref()`].
+        fn mark_complete_and_common_ref(&mut self) -> Result<negotiate::Action, negotiate::Error>;
+        /// Typically invokes [`negotiate::add_wants()`].
+        /// Returns `true` if wants were added, or `false` if the negotiation should be aborted.
+        #[must_use]
+        fn add_wants(&mut self, arguments: &mut fetch::Arguments, remote_ref_target_known: &[bool]) -> bool;
+        /// Typically invokes [`negotiate::one_round()`].
+        fn one_round(
+            &mut self,
+            state: &mut negotiate::one_round::State,
+            arguments: &mut fetch::Arguments,
+            previous_response: Option<&fetch::Response>,
+        ) -> Result<(negotiate::Round, bool), negotiate::Error>;
+    }
+
+    /// The outcome of [`fetch()`](crate::fetch()).
+    #[derive(Debug, Clone)]
+    pub struct Outcome {
+        /// The most recent server response.
+        ///
+        /// Useful to obtain information about new shallow boundaries.
+        pub last_response: fetch::Response,
+        /// Information about the negotiation to receive the new pack.
+        pub negotiate: NegotiateOutcome,
+    }
+
+    /// The negotiation-specific outcome of [`fetch()`](crate::fetch()).
+    #[derive(Debug, Clone)]
+    pub struct NegotiateOutcome {
+        /// The outcome of the negotiation stage of the fetch operation.
+        ///
+        /// If it is…
+        ///
+        /// * [`negotiate::Action::MustNegotiate`] there will always be a `pack`.
+        /// * [`negotiate::Action::SkipToRefUpdate`] there is no `pack` but references can be updated right away.
+        ///
+        /// Note that this is never [negotiate::Action::NoChange`] as this would mean there is no negotiation information at all
+        /// so this structure wouldn't be present.
+        pub action: negotiate::Action,
+        /// Additional information for each round of negotiation.
+        pub rounds: Vec<negotiate::Round>,
+    }
+
+    /// Information about the relationship between our refspecs, and remote references with their local counterparts.
+    ///
+    /// It's the first stage that offers connection to the server, and is typically required to perform one or more fetch operations.
+    #[derive(Default, Debug, Clone)]
+    pub struct RefMap {
+        /// A mapping between a remote reference and a local tracking branch.
+        pub mappings: Vec<refmap::Mapping>,
+        /// The explicit refspecs that were supposed to be used for fetching.
+        ///
+        /// Typically, they are configured by the remote and are referred to by
+        /// [`refmap::SpecIndex::ExplicitInRemote`] in [`refmap::Mapping`].
+        pub refspecs: Vec<gix_refspec::RefSpec>,
+        /// Refspecs which have been added implicitly due to settings of the `remote`, usually pre-initialized from
+        /// [`extra_refspecs` in RefMap options](refmap::init::Context).
+        /// They are referred to by [`refmap::SpecIndex::Implicit`] in [`refmap::Mapping`].
+        ///
+        /// They are never persisted nor are they typically presented to the user.
+        pub extra_refspecs: Vec<gix_refspec::RefSpec>,
+        /// Information about the fixes applied to the `mapping` due to validation and sanitization.
+        pub fixes: Vec<gix_refspec::match_group::validate::Fix>,
+        /// All refs advertised by the remote.
+        pub remote_refs: Vec<crate::handshake::Ref>,
+        /// The kind of hash used for all data sent by the server, if understood by this client implementation.
+        ///
